// ===== Alerte Tally → Telegram =====
// Reçoit les webhooks Tally (formulaire WO26DL) et envoie une alerte simple.
// À faire côté utilisateur :
//  1. Dans Tally → Settings du formulaire → Webhooks → Ajouter :
//     URL de production : https://n8n.rennesdev.fr/webhook/tally-alerte
//  2. Plus tard : ajouter le lien vers l'application où le texte du client est stocké
//     (constante LIEN_CLIENT ci-dessous, affichée dans le message dès qu'elle est remplie).
const CONFIG = {
  LIEN_CLIENT: '', // à remplir plus tard : lien vers l'appli où est stocké le texte du client
};

const body = $json.body || {};
const data = body.data || body || {};
const formName = data.formName || body.formName || 'Formulaire Tally';
const submissionId = data.submissionId || data.id || '';

// Tally envoie les champs dans data.fields (label + value) — on les affiche s'ils existent
let detail = '';
if (Array.isArray(data.fields)) {
  const lignesChamps = data.fields
    .map((f) => {
      let val = f.value;
      if (Array.isArray(val)) val = val.join(', ');
      if (val === null || val === undefined || val === '') return null;
      const label = f.label || f.id || '';
      return `${label} : ${String(val).slice(0, 200)}`;
    })
    .filter(Boolean)
    .slice(0, 8);
  if (lignesChamps.length) detail = lignesChamps.join('\n');
}

const lignes = [`📩 Nouveau message via Tally — ${formName}`];
if (submissionId) lignes.push(`Réponse : ${submissionId}`);
if (detail) lignes.push('', detail);
if (CONFIG.LIEN_CLIENT) lignes.push('', `➡️ ${CONFIG.LIEN_CLIENT}`);
lignes.push(`Reçu le ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })}`);

return [{ json: { text: lignes.join('\n') } }];
